    overlay.querySelectorAll("[data-factor-tile]").forEach(button=>{button.addEventListener("click",()=>{state.selectedTile=button.dataset.factorTile;save("Ficha seleccionada. Elige una región de la caja.")});button.addEventListener("dragstart",event=>{event.dataTransfer?.setData("text/plain",button.dataset.factorTile);state.selectedTile=button.dataset.factorTile})});
